Fixpoint words4_of_bytes (bs : list byte) : list word :=
  match bs with
  | b0 :: b1 :: b2 :: b3 :: rest => le_bytes_to_word [b0;b1;b2;b3] :: words4_of_bytes rest
  | _ => []
  end.

